/// Determines the safety of food based on the number of days past a certain date.
/// 
/// # Parameters
/// - `x`: The maximum number of days that food is considered safe.
/// - `a`: The date (in days) when the food was prepared.
/// - `b`: The current date (in days).
///
/// # Returns
/// A static string indicating the safety of the food:
/// - "delicious" if the food is fresh (days_past <= 0)
/// - "safe" if the food is still safe to eat (0 < days_past <= x)
/// - "dangerous" if the food is no longer safe (days_past > x)
///
/// # Verus Specifications
/// - Requires: `b >= a`
/// - Ensures: The return value is one of "delicious", "safe", or "dangerous".
#[verus::spec]
fn determine_food_safety(x: i8, a: i8, b: i8) -> &'static str {
    // Ensure that the current date is not before the preparation date
    assert!(b >= a); // This is a precondition that must hold

    let days_past = b - a;

    // Invariant: days_past is always equal to b - a
    // This invariant holds true throughout the function execution
    assert!(days_past == b - a);

    if days_past <= 0 {
        // Ensures that if days_past is less than or equal to 0, the food is "delicious"
        assert!(days_past <= 0);
        return "delicious";
    } else if days_past <= x {
        // Ensures that if days_past is between 1 and x, the food is "safe"
        assert!(days_past > 0 && days_past <= x);
        return "safe";
    } else {
        // Ensures that if days_past is greater than x, the food is "dangerous"
        assert!(days_past > x);
        return "dangerous";
    }
}